    else if (!(Option(e.tenantId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "MetadataVersionReleased.tenantId 必须存在"))
    // @knowledge 9c3f3c18-0255-4761-866d-bf637d6280fc@7b5b8fbe3b66a3c8
    // ir_evt_MetadataVersionReleased_timestamp
    else if (!(Option(e.timestamp).isDefined)) Some(iMadzError("EVENT_NO_TIMESTAMP", "MetadataVersionReleased.timestamp 不能为空"))
    else None

}
